import { criarCliente, type Cofre } from '../src/core/api/cliente';

const resposta = (status: number, corpo: unknown = {}) => ({ status, ok: status < 400, json: async () => corpo, text: async () => JSON.stringify(corpo) }) as unknown as Response;
function cofre(inicial?: { accessToken: string; refreshToken: string }): Cofre & { salvo: unknown } {
  const c = { salvo: inicial as unknown,
    ler: async () => c.salvo as never, salvar: async (t: unknown) => { c.salvo = t; }, limpar: async () => { c.salvo = null; } };
  return c as never;
}
const T = { accessToken: 'a1', refreshToken: 'r1' };

describe('cliente da API', () => {
  it('renovação é única com pedidos simultâneos', async () => {
    let renovacoes = 0;
    const f = jest.fn(async (url: string, init: RequestInit) => {
      if (url.endsWith('/auth/refresh')) { renovacoes++; return resposta(200, { accessToken: 'a2', refreshToken: 'r2' }); }
      return (init.headers as Record<string, string>).authorization === 'Bearer a2' ? resposta(200, { ok: 1 }) : resposta(401);
    });
    const c = criarCliente({ base: 'https://x', fetch: f as never, cofre: cofre(T), aoSair: jest.fn() });
    await Promise.all([c.get('/me'), c.get('/sessions'), c.get('/audit')]);
    expect(renovacoes).toBe(1);
  });

  it('401 sem renovação possível sai para o login e limpa as credenciais', async () => {
    const aoSair = jest.fn(); const k = cofre(T);
    const f = jest.fn(async () => resposta(401));
    const c = criarCliente({ base: 'https://x', fetch: f as never, cofre: k, aoSair });
    await expect(c.get('/me')).rejects.toMatchObject({ http: 401 });
    expect(aoSair).toHaveBeenCalled();
    expect(k.salvo).toBeNull();
  });

  it('falha de rede na renovação não desloga', async () => {
    const aoSair = jest.fn(); const k = cofre(T);
    const f = jest.fn(async (url: string) => { if (url.endsWith('/auth/refresh')) throw new Error('rede'); return resposta(401); });
    const c = criarCliente({ base: 'https://x', fetch: f as never, cofre: k, aoSair });
    await expect(c.get('/me')).rejects.toBeTruthy();
    expect(aoSair).not.toHaveBeenCalled();
    expect(k.salvo).toEqual(T);
  });

  it('falha de rede num comando vira UNKNOWN e não repete sozinho', async () => {
    const f = jest.fn(async () => { throw new Error('caiu'); });
    const c = criarCliente({ base: 'https://x', fetch: f as never, cofre: cofre(T), aoSair: jest.fn() });
    const r = await c.enviarOperacao('/qualquer', { operationId: 'op' });
    expect(r).toEqual({ operationId: 'op', status: 'UNKNOWN' });
    expect(f).toHaveBeenCalledTimes(1);
  });

  it('5xx num comando também vira UNKNOWN', async () => {
    const f = jest.fn(async () => resposta(503, { codigo: 'UNAVAILABLE' }));
    const c = criarCliente({ base: 'https://x', fetch: f as never, cofre: cofre(T), aoSair: jest.fn() });
    expect(await c.enviarOperacao('/q', { operationId: 'op' })).toEqual({ operationId: 'op', status: 'UNKNOWN' });
    expect(f).toHaveBeenCalledTimes(1);
  });

  it('nunca usa AsyncStorage para credenciais', () => {
    const fonte = require('node:fs').readFileSync('src/core/security/cofre.ts', 'utf8');
    expect(fonte).toContain('expo-secure-store');
    expect(fonte).not.toMatch(/AsyncStorage/);
  });
});
